import{_ as a,o as n,c as s,ai as l}from"./chunks/framework.Ai2o9gNv.js";const e="/assets/image-20251221084347197.DSFWfKoi.png",t="/assets/image-20251221084405992.D0N1N5EB.png",b=JSON.parse('{"title":"WordSea - 专业词云可视化工具","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/iflow 帮你极速实现 纯前端的 词云网站/README.md","filePath":"AI人工智能/iflow 帮你极速实现 纯前端的 词云网站/README.md","lastUpdated":1766289541000,"__rawMarkdown":"# WordSea - 专业词云可视化工具\\n\\nWordSea 是一个简洁、强大的在线词云生成工具。它可以将您输入的文本内容智能分析，提取关键词并生成精美的词云图片。支持中英文混合分词，提供多种形状选择，是文本可视化和数据展示的得力助手。\\n\\n##  主要功能\\n\\n- **智能分词**：自动识别中文和英文内容，统计词频。\\n- **多种形状**：内置多种词云形状，包括：\\n  - 圆形 (Circle)\\n  - 心形 (Cardioid)\\n  - 星星 (Star)\\n  - 方形 (Square)\\n  - 菱形 (Diamond)\\n  - 三角形 (Triangle)\\n  - 五边形 (Pentagon)\\n- **即时预览**：输入文本后点击生成，立即在画布上看到效果。\\n- **图片导出**：支持将生成的词云下载为图片格式，方便分享和使用。\\n- **历史记录**：自动保存生成历史，方便随时回溯查看。\\n- **完全免费**：基于纯前端技术开发，无后台数据存储，安全隐私。\\n\\n##  快速开始\\n\\n### 在线使用\\n```\\nhttps://wordsea.zbztb.cn/\\n```\\n\\n![image-20251221084347197](assets/image-20251221084347197.png)\\n\\n### 本地运行\\n\\nWordSea 是一个纯静态网页应用，无需复杂的后端环境配置。\\n\\n#### 系统要求\\n- 任何现代浏览器（Chrome、Firefox、Safari、Edge 等）\\n- 无需额外依赖\\n\\n#### 安装步骤\\n\\n1. **克隆项目**\\n   \\n   ```bash\\n   git clone git@github.com:itcastWsy/wordSea.git\\n   cd wordSea\\n   ```\\n   \\n2. **打开应用**\\n   \\n   - **方式一**：直接在浏览器中打开 `index.html` 文件\\n   - **方式二**：使用 VS Code 的 Live Server 插件运行，获得更好的开发体验\\n   - **方式三**：使用 Python 启动本地服务器（推荐）：\\n     ```bash\\n     # Python 3\\n     python -m http.server 8000\\n     \\n     # Python 2\\n     python -m SimpleHTTPServer 8000\\n     ```\\n  然后在浏览器中访问 `http://localhost:8000`\\n   \\n3. **验证安装**\\n   - 打开应用后，您应该能看到 WordSea 的主界面\\n   - 左侧为文本输入区域，右侧为词云显示区域\\n   - 顶部导航栏包含下载功能按钮\\n\\n## 详细使用指南\\n\\n### 基本使用步骤\\n\\n1. **准备文本内容**\\n   - 收集您想要分析的文本内容（文章、评论、关键词列表等）\\n   - 支持中英文混合内容\\n\\n2. **输入文本**\\n   - 在左侧文本框中粘贴或输入您的文本内容\\n   - 文本长度建议在 100-5000 字之间，以获得最佳效果\\n\\n3. **生成词云**\\n   - 点击\\"生成词云\\"按钮\\n   - 系统将自动进行分词和词频统计\\n   - 词云将在右侧画布上实时渲染\\n\\n4. **调整样式**\\n   - 在右侧控制面板选择不同的形状：\\n     - 圆形 (Circle)\\n     - 心形 (Cardioid)\\n     - 星星 (Star)\\n     - 方形 (Square)\\n     - 菱形 (Diamond)\\n     - 三角形 (Triangle)\\n     - 五边形 (Pentagon)\\n   - 词云会根据您的选择实时更新\\n\\n5. **保存结果**\\n   - 点击顶部导航栏的下载图标\\n   - 选择保存位置和文件名\\n   - 词云将以 PNG 格式保存到本地\\n\\n### 高级技巧\\n\\n- **关键词优化**：在文本中使用重复的关键词可以增强其在词云中的显示效果\\n- **中英文混合**：系统会自动识别中英文，无需特殊处理\\n- **批量处理**：可以一次性处理多段文本，系统会合并分析\\n- **历史记录**：浏览器会自动保存您的使用历史，方便回溯查看\\n\\n##  技术栈\\n\\n- **HTML5 / CSS3**: 构建响应式用户界面。\\n- **JavaScript (ES6+)**: 处理核心逻辑和交互。\\n- **[wordcloud2.js](https://github.com/timdream/wordcloud2.js)**: 强大的词云生成库。\\n- **[html2canvas](https://html2canvas.hertzen.com/)**: 用于将 DOM 元素转换为 Canvas 进行截图下载。\\n\\n##  使用 iFlow CLI 开发与维护\\n\\n### 什么是 iFlow CLI\\n\\niFlow CLI 是一款强大的终端AI助手，专为开发者设计，可以分析代码、执行编程任务、处理文件操作。它是维护和扩展 WordSea 项目的理想工具。\\n\\n![image-20251221084405992](assets/image-20251221084405992.png)\\n\\n### 安装 iFlow CLI\\n\\n#### 系统要求\\n- Node.js 22+\\n- 4GB+ 内存\\n- 互联网连接\\n\\n#### Windows 安装步骤\\n\\n1. **安装 Node.js**\\n   - 访问 https://nodejs.org/zh-cn/download 下载最新的 Node.js 安装程序\\n   - 运行安装程序来安装 Node.js\\n   - 重启终端（CMD 或 PowerShell）\\n\\n2. **安装 iFlow CLI**\\n   ```bash\\n   npm install -g @iflow-ai/iflow-cli@latest\\n   ```\\n\\n3. **验证安装**\\n   ```bash\\n   iflow --version\\n   ```\\n\\n4. **启动 iFlow CLI**\\n   ```bash\\n   iflow\\n   ```\\n\\n### 配置 iFlow CLI\\n\\n#### 登录方式（推荐使用 Login with iFlow）\\n\\n1. 运行 `iflow` 启动 CLI\\n2. 选择 \\"Login with iFlow\\" 登录选项\\n3. CLI 会自动打开浏览器跳转到心流平台\\n4. 完成注册/登录后授权 iFlow CLI\\n5. 自动返回终端，开始使用\\n\\n### 使用 iFlow CLI 维护 WordSea\\n\\n#### 项目分析\\n```bash\\n# 在 WordSea 项目目录下\\ncd /path/to/wordSea\\niflow\\n> /init\\n> 分析这个项目的结构和主要功能\\n```\\n\\n#### 代码优化\\n```bash\\niflow\\n> 帮我优化 app.js 中的代码性能\\n> 检查 style.css 中是否有冗余样式\\n```\\n\\n#### 功能扩展\\n```bash\\niflow\\n> 为 WordSea 添加一个新的词云形状：六边形\\n> 实现词云颜色主题切换功能\\n```\\n\\n#### 问题诊断\\n```bash\\niflow\\n> 检查为什么词云生成时出现性能问题\\n> 帮我修复在移动端的显示问题\\n```\\n\\n#### 文件操作\\n```bash\\niflow\\n> !ls -la\\n> 帮我分析这个目录结构，建议如何整理文件\\n> 创建一个备份当前版本的脚本\\n```\\n\\n### 常用 iFlow CLI 命令\\n\\n| 命令 | 功能 | 示例 |\\n|---|---|---|\\n| `/help` | 查看帮助 | `/help` |\\n| `/init` | 分析项目结构 | `/init` |\\n| `/clear` | 清空对话历史 | `/clear` |\\n| `/exit` | 退出CLI | `/exit` |\\n| `!命令` | 执行系统命令 | `!npm install` |\\n| `@文件路径` | 引用文件 | `@app.js` |\\n| `$agent` | 使用专业代理 | `$code-reviewer` |\\n\\n### 使用 iFlow CLI 的最佳实践\\n\\n1. **项目初始化**：使用 `/init` 命令快速了解项目结构\\n2. **代码审查**：定期使用 `$code-reviewer` 检查代码质量\\n3. **功能开发**：通过自然语言描述需求，让 iFlow CLI 帮助实现\\n4. **问题解决**：遇到问题时，详细描述现象，请求诊断和解决方案\\n5. **文档维护**：让 iFlow CLI 帮助更新和优化项目文档\\n\\n### 为什么选择 iFlow CLI\\n\\n- **智能理解**：能够理解项目上下文，提供精准的代码建议\\n- **多模态能力**：支持图像理解，可以分析 UI 设计稿\\n- **网络搜索**：内置网络搜索能力，获取最新技术信息\\n- **无缝集成**：与现有开发工具链完美集成\\n- **持续学习**：基于最新技术栈，提供前沿的开发建议\\n\\n通过 iFlow CLI，您可以更高效地维护和扩展 WordSea 项目，实现功能的快速迭代和优化。\\n\\n## 使用指南\\n\\n1. **输入文本**：在左侧文本框中粘贴或输入您想要分析的文章、评论或关键词列表。\\n2. **生成词云**：点击\\"生成词云\\"按钮，系统将自动分析并渲染。\\n3. **调整样式**：在右侧控制面板选择不同的形状，词云会实时更新。\\n4. **下载保存**：点击顶部导航栏的下载图标，将当前词云保存为图片。\\n\\n##  贡献指南\\n\\n欢迎提交 Issue 和 Pull Request 来改进 WordSea！\\n\\n1. Fork 本仓库\\n2. 新建 feature 分支 (`git checkout -b feature/AmazingFeature`)\\n3. 提交更改 (`git commit -m \'Add some AmazingFeature\'`)\\n4. 推送到分支 (`git push origin feature/AmazingFeature`)\\n5. 提交 Pull Request\\n\\n> https://github.com/itcastWsy/wordSea\\n\\n##  作者信息\\n\\n- **博客**: [https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n- **邮箱**: [yeah126139163@163.com](mailto:yeah126139163@163.com)\\n- **微信**: w846903522\\n- **公众号**: HarmonyOS 万少\\n\\n##  开源协议\\n\\n本项目采用 MIT License 开源协议。\\n"}'),r={name:"AI人工智能/iflow 帮你极速实现 纯前端的 词云网站/README.md"};function o(h,i,d,p,c,g){return n(),s("div",null,[...i[0]||(i[0]=[l("",63)])])}const k=a(r,[["render",o]]);export{b as __pageData,k as default};
